40	
41	    const handleClose = useCallback(() => {
42	        onCancel();
43	        setTimeout(() => {
44	            setChallengeTxtReply('');
45	        }, 1000);
46	    }, [onCancel]);
47	
48	    const handleConfirm = useCallback(() => {
49	        onConfirm();
50	        setTimeout(() => {
51	            setChallengeTxtReply('');
52	        }, 1000);
53	    }, [onConfirm]);
54	
55	    return (
56	        <Dialog open={open} data-testid='confirmation-dialog'>
57	            <DialogPortal>
